// ── EMI MESSAGES ───────────────────────────────────────────────────────────
// Admin-only tab: generates WhatsApp click-to-chat links for EMI-related messages

const UPI_ID = 'paytmqr6njiga@ptys';

// ── UPI QR ────────────────────────────────────────────────────────────────
// The Send button is a wa.me click-to-chat link, and that link carries TEXT
// ONLY - a web page cannot paste an image into WhatsApp. So the QR image is
// copied to the clipboard on the way out and pasted into the chat by hand.
//
// Where the QR bytes come from, in order:
//   1. assets/upi-qr.png - the source of truth. Read with fetch over http(s).
//   2. The image the user loads by hand ("Load assets/upi-qr.png" in the
//      modal), remembered in localStorage. A page opened as file:// cannot
//      read a local file at all - Chrome blocks fetch, XHR and canvas alike -
//      so this is the only way the app can copy the exact file there.
//   3. The base64 copy embedded below, so the app works out of the box.
//
// The PNG is read ONCE, when the tab opens, so a Send click never waits on
// the network: the clipboard write then happens in the same tick as the click
// and the browser still sees a live user gesture.
const QR_PNG_B64 = '';

// v2 invalidates any copy stored under the old key (that was a different image).
const QR_STORE_KEY = 'aks_qr_png_dataurl_v2';

let _qrBytes = null;      // Uint8Array of the PNG, ready for the clipboard
let _qrMime = 'image/png';
let _qrSource = 'none';   // 'file' | 'stored' | 'embedded'

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function bytesToB64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i += 8192) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 8192));
  }
  return btoa(bin);
}

function qrDataUrl() {
  const bytes = _qrBytes || b64ToBytes(QR_PNG_B64);
  return 'data:' + _qrMime + ';base64,' + bytesToB64(bytes);
}

function qrStatusText() {
  if (_qrSource === 'file') return 'Using assets/upi-qr.png';
  if (_qrSource === 'stored') return 'Using the image you loaded (remembered in this browser)';
  if (_qrSource === 'embedded') return 'Using the built-in copy - load assets/upi-qr.png to copy the file itself';
  return '';
}

function applyQr(bytes, mime, source) {
  _qrBytes = bytes;
  _qrMime = mime || 'image/png';
  _qrSource = source;
  const img = $('qr-modal-img');
  if (img) {
    // A file:// page can still DISPLAY the file (only reading its bytes is
    // blocked), so show the real file there rather than the built-in copy.
    if (source === 'embedded' && location.protocol === 'file:') img.src = 'assets/upi-qr.png?v=' + Date.now();
    else img.src = qrDataUrl();
  }
  const note = $('qr-modal-note');
  if (note) note.textContent = qrStatusText();
}

// The copy the user loaded by hand, if any.
function storedQr() {
  try {
    const url = localStorage.getItem(QR_STORE_KEY);
    if (!url) return null;
    const parts = url.split(',');
    if (parts.length < 2) return null;
    const bytes = b64ToBytes(parts[1]);
    if (bytes.length < 100) return null;
    const mime = (url.slice(5).split(';')[0] || 'image/png');
    return { bytes: bytes, mime: mime, url: url };
  } catch (e) { return null; }
}

// Loads the PNG once, when the tab opens.
async function loadQr() {
  try {
    const res = await fetch('assets/upi-qr.png?t=' + Date.now());
    if (res.ok) {
      const buf = new Uint8Array(await res.arrayBuffer());
      if (buf.length > 100) { applyQr(buf, 'image/png', 'file'); return; }
    }
  } catch (e) { /* file:// - the page is not allowed to read the local file */ }
  const stored = storedQr();
  if (stored) { applyQr(stored.bytes, stored.mime, 'stored'); return; }
  applyQr(b64ToBytes(QR_PNG_B64), 'image/png', 'embedded');
}

// Points the app at the QR file once; the bytes are remembered, so every
// later Send copies that exact image.
function qrFilePicked(input) {
  const f = input.files && input.files[0];
  if (!f) return;
  const fr = new FileReader();
  fr.onload = () => {
    const url = String(fr.result);
    const parts = url.split(',');
    if (parts.length < 2) { showAlert('That file could not be read.', 'w'); return; }
    const bytes = b64ToBytes(parts[1]);
    if (bytes.length < 100) { showAlert('That file is not a usable image.', 'w'); return; }
    applyQr(bytes, (url.slice(5).split(';')[0] || 'image/png'), 'stored');
    try { localStorage.setItem(QR_STORE_KEY, url); } catch (e) {}
    showAlert('QR image loaded - Send now copies this exact file.', 's');
  };
  fr.readAsDataURL(f);
}

function openQrModal() {
  const m = $('qr-modal');
  if (m) m.style.display = 'flex';
  if (!_qrBytes) loadQr();
}

function closeQrModal() {
  const m = $('qr-modal');
  if (m) m.style.display = 'none';
}

// ── Send: QR to clipboard, then open WhatsApp ────────────────────────────
// The Blob is built synchronously and the clipboard write is issued in the
// same tick as the click, which is what the browser's user-gesture check
// looks at. Any await before the write can lose the gesture and make the
// browser refuse the copy.
function sendWithQr(url) {
  const bytes = _qrBytes || b64ToBytes(QR_PNG_B64);
  const blob = new Blob([bytes], { type: _qrMime });
  copyQrToClipboard(blob).then(res => {
    if (!res.ok) {
      console.warn('QR clipboard write failed:', res.reason);
      showAlert('QR auto-copy failed (' + res.reason + ') - open the QR Code button, copy the image, and paste it into the chat.', 'w');
      openQrModal();
    }
    const w = window.open(url, '_blank');
    if (!w) location.href = url;
  });
  return false;   // handled here, not by the link default
}

async function copyQrToClipboard(blob) {
  try {
    if (!navigator.clipboard || !navigator.clipboard.write) return { ok: false, reason: 'no clipboard API' };
    if (typeof ClipboardItem === 'undefined') return { ok: false, reason: 'browser cannot copy images' };
    await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
    return { ok: true, reason: '' };
  } catch (err) {
    return { ok: false, reason: (err && err.name) || 'unknown error' };
  }
}

function ymd(dt) {
  return dt.getFullYear() + '-' + String(dt.getMonth()+1).padStart(2,'0') + '-' + String(dt.getDate()).padStart(2,'0');
}

function parseDate(str) {
  if (!str) return null;
  const d = new Date(str + 'T00:00:00');
  return isNaN(d) ? null : d;
}

// Shared by initEmiMsgsPage and the live path: turns Config's lastMessageSent
// into the From date plus an explanation of where it came from.
function applyMsgConfig(lastSent, today) {
  const last = parseDate(lastSent);
  if (lastSent && last) {
    last.setDate(last.getDate() + 1);
    $('emsg-from').value = ymd(last);
    $('emsg-from-label').textContent = '(last marked: ' + lastSent + ', +1 day)';
  } else if (lastSent) {
    $('emsg-from').value = today;
    $('emsg-from-label').textContent = '(invalid last-sent date)';
  } else {
    $('emsg-from').value = today;
    $('emsg-from-label').textContent = '(no last-sent date)';
  }
}

// No network in the happy path. S.snapConfig is carried by every snapshot (and
// persisted by CACHE_KEYS), and #emsg-from has no HTML default — so painting it
// synchronously is the whole difference between "instant" and "blank until
// readConfig comes back". readConfig is asked only when the snapshot has not
// produced a value yet (first ever load, or the Worker is down).
function initEmiMsgsPage() {
  const today = ymd(new Date());
  $('emsg-start').value = today;
  $('emsg-results').innerHTML = '';
  $('emsg-mark-wrap').style.display = 'none';
  loadQr();   // one fetch, so the Send click can copy the QR without waiting

  if (S.snapConfig !== undefined && S.snapConfig !== null) {
    applyMsgConfig(S.snapConfig, today);
    return;
  }
  applyMsgConfig('', today);   // field is never left blank while we wait
  if (!S.sheetsUrl) return;
  gasGet('readConfig').then(d => {
    if (d && d.ok) {
      S.snapConfig = d.lastMessageSent;
      cacheState();
      if ($('emsg-from')) applyMsgConfig(d.lastMessageSent, today);
    }
  }).catch(() => {});
}

async function generateMessages() {
  const fromVal  = $('emsg-from').value;
  const endVal   = $('emsg-start').value;
  if (!fromVal || !endVal) { showAlert('Please fill both From and To dates.', 'e'); return; }

  const startDate = parseDate(fromVal);
  const endDate   = parseDate(endVal);
  if (!startDate || !endDate) { showAlert('Invalid date.', 'e'); return; }
  if (startDate > endDate) { showAlert('From date cannot be after To date.', 'e'); return; }

  showLoader();
  try {
    let loans = null;
    let revisedEntries = null;

    // readAllLoansForMsgs is the same 93-column buildFullLoan() output that
    // readAllLoans produces — which every snapshot already carries — and
    // readAllLoans additionally merges lockRemoved and enriches miscType, so it
    // is a strict superset. When full rows are in hand there is nothing worth
    // fetching: render straight from memory instead of waiting on a duplicate
    // ~20 s read.
    if (S._fullLoaded && Array.isArray(S.sheetLoans) && S.sheetLoans.length) {
      loans = S.sheetLoans;
      revisedEntries = Array.isArray(S.revisedDates) ? S.revisedDates : [];
    } else {
      // Fallback: snapshot never landed (or the Worker is down) — keep the
      // old behaviour rather than show nothing.
      const [lData, rData] = await Promise.all([
        gasGet('readAllLoansForMsgs'),
        gasGet('readRevisedDates'),
      ]);
      if (!lData.ok) {
        // A transport failure is not a confirmed failure — say so, and don't
        // dress it up as a data error.
        if (lData.transport) showAlert("Couldn't reach Google to load loans. Refresh the page to retry.", 'w');
        else showAlert('Failed to load loans: ' + (lData.error||''), 'e');
        return;
      }
      loans = lData.loans || [];
      revisedEntries = (rData.ok && rData.dates) ? rData.dates : [];
    }

    // Build lookup: loanId -> { emiNum, note, revisedDate }[]
    const revisedLookup = {};
    revisedEntries.forEach(entry => {
      const id = entry.loanId || '';
      if (!revisedLookup[id]) revisedLookup[id] = [];
      revisedLookup[id].push({ emiNum: entry.emiNum, note: entry.note,
                               revisedDate: entry.revisedDate || '' });
    });

    const messages = [];

    loans.forEach(loan => {
      const name  = loan.customerName || '';
      const phone = loan.phone || '';
      if (!phone) return;
      // Skip defaulted loans entirely — no messages for bad loans
      if (loan.isDefaulted) return;
      const li    = loan.loanId || '';

      const loanTemplates = {
        'Welcome':      loan.welcomeMsgText,
        'EMI Reminder': loan.emiMsgText,
        'Last Date':    loan.lastDateMsgText,
        'Thank You':    loan.thankYouMsgText,
        'Loan Closing': loan.loanClosingMsgText,
        'Revised Date': loan.revisedDateMsg,
      };

      // `label` is the SECTION the row lands in; `extra.tplKey` is the template
      // it is written from. They are usually the same, but a revised EMI's
      // reminder/last-date messages belong in the Revised Date section while
      // still being written from the reminder/last-date templates.
      // `extra.date` is the DUE date the text should quote — `dateStr` is only
      // the day the message goes out (7/2/1 day(s) earlier for a reminder).
      function addIfInRange(label, dateStr, extra) {
        const template = loanTemplates[(extra && extra.tplKey) || label];
        if (!dateStr || !template) return;
        const dt = parseSheetDate(dateStr);
        if (!dt) return;
        const t = dt.getTime();
        if (t < startDate.getTime() || t > endDate.getTime()) return;
        const amt = extra && extra.amount != null ? extra.amount : (loan.monthlyEmi || '');
        const dueForText = (extra && extra.date) || dateStr;
        let msg = template
          .replace(/\{customer\}/g, name)
          .replace(/\{loan\}/g, li)
          .replace(/\{amount\}/g, amt)
          .replace(/\{date\}/g, fmtDisplayDate(dueForText))
          .replace(/\{total\}/g, loan.totalPending != null ? loan.totalPending : amt);
        if (extra && extra.emiNum != null) {
          msg = msg.replace(/\{emi\}/g, extra.emiNum);
        } else {
          msg = msg.replace(/\{emi\}/g, '');
        }
        const upi = `upi://pay?pa=${UPI_ID}&pn=AKS+Finance&am=${amt}&cu=INR&tn=EMI+${li}`;
        msg = msg.replace(/\{upilink\}/g, upi);
        messages.push({ label, phone, customerName: name, loanId: li, emiNum: extra && extra.emiNum, date: dateStr, msg });
      }

      // Skip Welcome and Revised Date if loan is already completed
      if (!loan.emiCompleted) {
        if (loan.billDate) {
          const wd = parseSheetDate(loan.billDate);
          if (wd) { wd.setDate(wd.getDate() + 1); addIfInRange('Welcome', ymd(wd)); }
        }

        if (loan.revisedDateData && loan.revisedDateMsg) {
          const revDt = parseSheetDate(loan.revisedDateData);
          const todayMs = parseDate(ymd(new Date())).getTime();
          // Skip if revised date has already passed — no point sending reminder for a past date
          if (!revDt || revDt.getTime() >= todayMs) {
            const revs = revisedLookup[li] || [];
            // Skip if all revised EMIs have been received
            const anyUnreceived = revs.some(r => {
              if (r.note === 'Mobile Jabt') return false;
              if (r.note === 'Foreclosure') return false;
              const slot = (loan.slots || []).find(s => s.num === r.emiNum);
              return slot && !slot.received;
            });
            if (anyUnreceived || revs.length === 0) {
              // `revisedDateData` is ONE date for the whole loan, so the EMI
              // column has to name the EMI that this date belongs to. Listing
              // every EMI the loan has ever revised showed "3, 3, 4, 4, 5" for
              // a message that is only about one of them.
              const revMs = revDt ? revDt.getTime() : null;
              const forThisDate = revMs === null ? [] : revs.filter(r => {
                const d = parseSheetDate(r.revisedDate);
                return d && d.getTime() === revMs;
              });
              const emiLabels = [];
              forThisDate.forEach(r => {
                const v = r.note === 'Mobile Jabt' ? 'Mobile Jabt' : r.emiNum;
                if (v == null || emiLabels.indexOf(v) !== -1) return;
                emiLabels.push(v);
              });
              const emiLabel = emiLabels.join(', ');
              addIfInRange('Revised Date', loan.revisedDateData, { amount: loan.monthlyEmi, emiNum: emiLabel || undefined });
            }
          }
        }
      }

      // Process slots — only generate Last Date/EMI Reminder for the first unreceived slot
      const slots = loan.slots || [];
      const unreceived = slots.filter(s => !s.received).map(s => s.num);
      const firstDue = unreceived.length ? Math.min(...unreceived) : Infinity;
      const loanRevs = revisedLookup[li] || [];
      slots.forEach(slot => {
        const sd = slot.scheduledDate;
        if (!sd) return;
        const sdDt = parseSheetDate(sd);
        if (!sdDt) return;

        // scheduledDate is only ever the EMI start date plus N months — it never
        // sees the Revised_Dates sheet. Anything keyed off it (Last Date, the
        // reminder offsets) therefore fired on the ORIGINAL due date: a loan
        // revised from 22-Oct to 19-Oct still sent its -7 reminder on 15-Oct.
        // The sheet is append-only in time order, so the last row recorded for
        // this EMI number is the revision that is actually in force.
        let dueStr = sd, dueDt = sdDt, wasRevised = false;
        for (const r of loanRevs) {
          if (r.emiNum !== slot.num || !r.revisedDate) continue;
          const rd = parseSheetDate(r.revisedDate);
          if (rd) { dueStr = r.revisedDate; dueDt = rd; wasRevised = true; }
        }
        const dueTime = dueDt.getTime();

        // A revised EMI's messages belong in the Revised Date section — Last Date
        // and EMI Reminder would put a date that has already been moved under the
        // original schedule. The wording still comes from those two templates.
        const section    = wasRevised ? 'Revised Date' : 'Last Date';
        const remindSec  = wasRevised ? 'Revised Date' : 'EMI Reminder';

        // Last Date and EMI Reminder: only for the first unreceived slot
        if (slot.num === firstDue && !slot.received && dueTime >= endDate.getTime()) {
          const lastDateInRange = dueTime >= startDate.getTime() && dueTime <= endDate.getTime();
          if (lastDateInRange)
            addIfInRange(section, dueStr, { emiNum: slot.num, tplKey: 'Last Date' });

          // EMI Reminder: suppressed if Last Date is in range for this slot
          if (!lastDateInRange) {
            const reminderOffsets = [-7, -2, -1];
            let selectedOffset = null;
            for (const offset of reminderOffsets) {
              const d = new Date(dueDt);
              d.setDate(d.getDate() + offset);
              const t = d.getTime();
              if (t >= startDate.getTime() && t <= endDate.getTime()) selectedOffset = offset;
            }
            if (selectedOffset !== null) {
              const rd = new Date(dueDt);
              rd.setDate(rd.getDate() + selectedOffset);
              // Sent on rd, but {date} in the text must quote the DUE date.
              addIfInRange(remindSec, ymd(rd),
                { emiNum: slot.num, amount: loan.monthlyEmi, date: dueStr, tplKey: 'EMI Reminder' });
            }
          }
        }
      });

      const rcvSlots = slots.filter(s => s.received && s.receivedDate);

      // Thank You: exactly ONE per loan — for the most recently paid EMI. It used
      // to be emitted inside the slot loop, so a multi-EMI payment (or any
      // customer who paid twice inside the window) produced one message per
      // covered EMI. Latest receivedDate wins; a same-day payment covering
      // several EMIs falls back to the highest EMI number.
      if (rcvSlots.length) {
        let lastPaid = rcvSlots[0];
        for (let i = 1; i < rcvSlots.length; i++) {
          const a = parseSheetDate(lastPaid.receivedDate);
          const b = parseSheetDate(rcvSlots[i].receivedDate);
          const at = a ? a.getTime() : 0;
          const bt = b ? b.getTime() : 0;
          if (bt > at || (bt === at && rcvSlots[i].num > lastPaid.num)) lastPaid = rcvSlots[i];
        }
        const td = parseSheetDate(lastPaid.receivedDate);
        if (td) { td.setDate(td.getDate() + 1); addIfInRange('Thank You', ymd(td), { emiNum: lastPaid.num }); }
      }

      if (loan.emiCompleted) {
        const lastRcv = rcvSlots[rcvSlots.length - 1];
        if (lastRcv && lastRcv.receivedDate) {
          const cd = parseSheetDate(lastRcv.receivedDate);
          if (cd) { cd.setDate(cd.getDate() + 1); addIfInRange('Loan Closing', ymd(cd), { amount: loan.totalPending || loan.monthlyEmi }); }
        }
      }
    });

    // Suppress Thank You when Loan Closing exists for same loanId
    const closingLoans = new Set(messages.filter(m => m.label === 'Loan Closing').map(m => m.loanId));
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i].label === 'Thank You' && closingLoans.has(messages[i].loanId)) messages.splice(i, 1);
    }

    // One row per loan, per section, per send day. A revised loan can reach the
    // Revised Date section twice on the same day: once from the loan-level
    // `revisedDateData` announcement and once from the revised EMI's own Last
    // Date / reminder message (both were routed here deliberately). The table
    // shows no message text, so the admin just saw the same loan twice with no
    // way to tell them apart. The announcement is written for exactly this
    // event, so it stays and the second one goes. `emiNum` is deliberately NOT
    // in the key: the announcement names EMIs as '3, 4' while the EMI message
    // carries the number 3, and they are still the same message.
    const seenMsg = new Set();
    for (let i = 0; i < messages.length; ) {
      const key = messages[i].label + '|' + messages[i].loanId + '|' + messages[i].date;
      if (seenMsg.has(key)) messages.splice(i, 1);
      else { seenMsg.add(key); i++; }
    }

    const TYPE_ORDER = { 'Welcome':1, 'Loan Closing':2, 'Thank You':3, 'Revised Date':4, 'Last Date':5, 'EMI Reminder':5 };
    messages.sort((a, b) =>
      (TYPE_ORDER[a.label]||99) - (TYPE_ORDER[b.label]||99) ||
      a.date.localeCompare(b.date) ||
      a.customerName.localeCompare(b.customerName)
    );
    renderMessageResults(messages);
    $('emsg-mark-wrap').style.display = messages.length ? 'block' : 'none';
  } catch (err) { showAlert('Error: ' + err.message, 'e'); }
  finally { hideLoader(); }
}

const _emsgCollapsed = {};

function renderMessageResults(messages) {
  const el = $('emsg-results');
  if (!messages.length) {
    el.innerHTML = '<div class="card" style="text-align:center;color:#888;font-size:13px">No messages to send in this date range.</div>';
    return;
  }

  const TYPE_META = {
    'Welcome':      { color:'#0F6E56', bg:'#E1F5EE', icon:'\uD83D\uDC4B' },
    'Loan Closing': { color:'#888',    bg:'#F1EFE8', icon:'\uD83D\uDD12' },
    'Thank You':    { color:'#1A73E8', bg:'#E8F0FE', icon:'\u2705' },
    'Revised Date': { color:'#0F6E56', bg:'#E1F5EE', icon:'\uD83D\uDCC5' },
    'Last Date':    { color:'#A32D2D', bg:'#FCEBEB', icon:'\u26A0\uFE0F' },
    'EMI Reminder': { color:'#BA7517', bg:'#FAEEDA', icon:'\uD83D\uDD14' },
  };
  const TYPE_ORDER = { 'Welcome':1, 'Loan Closing':2, 'Thank You':3, 'Revised Date':4, 'Last Date':5, 'EMI Reminder':5 };

  const groups = {};
  messages.forEach(m => { if (!groups[m.label]) groups[m.label] = []; groups[m.label].push(m); });

  const sortedLabels = Object.keys(groups).sort((a, b) => (TYPE_ORDER[a]||99) - (TYPE_ORDER[b]||99));
  sortedLabels.forEach(l => { if (_emsgCollapsed[l] === undefined) _emsgCollapsed[l] = false; });

  function toggle(label) { _emsgCollapsed[label] = !_emsgCollapsed[label]; renderMessageResults(messages); }

  el.innerHTML =
    `<div style="font-size:12px;color:#888;margin-bottom:0.5rem">${messages.length} message(s) found</div>` +
    sortedLabels.map(label => {
      const group = groups[label];
      const meta  = TYPE_META[label] || { color:'#888', bg:'#F1EFE8', icon:'\uD83D\uDCE7' };
      const collapsed = _emsgCollapsed[label];
      return `<div class="card" style="margin-bottom:0.5rem;padding:0;overflow:hidden">
        <div onclick="window.__emsgToggle('${label}')" style="display:flex;align-items:center;gap:8px;padding:10px 12px;cursor:pointer;background:${meta.bg};user-select:none">
          <span style="font-size:14px">${collapsed ? '\u25B6' : '\u25BC'}</span>
          <span style="font-size:12px;font-weight:600;color:${meta.color}">${meta.icon} ${label}</span>
          <span style="font-size:11px;color:#888;margin-left:auto">${group.length}</span>
        </div>
        ${collapsed ? '' :
          `<div style="overflow-x:auto"><table class="emi-table" style="width:100%"><thead><tr>
            <th>Customer</th><th>Phone</th><th>Loan</th><th>EMI</th><th>Date</th><th>Action</th>
          </tr></thead><tbody>` +
          group.map(m => {
            const url = `https://wa.me/91${m.phone}?text=${encodeURIComponent(m.msg)}`;
            return `<tr>
              <td style="white-space:nowrap">${m.customerName}</td>
              <td style="white-space:nowrap">${m.phone}</td>
              <td style="white-space:nowrap">${m.loanId}</td>
              <td>${m.emiNum || '\u2014'}</td>
              <td style="white-space:nowrap">${fmtDisplayDate(m.date)}</td>
              <td><a href="${url}" target="_blank" class="btn btn-sm" style="background:#25D366;color:#fff;border-color:#25D366;text-decoration:none" onclick="return sendWithQr(this.href)">\uD83D\uDCF1 Send</a></td>
            </tr>`;
          }).join('') +
          `</tbody></table></div>`
        }
      </div>`;
    }).join('');

  window.__emsgToggle = toggle;
}

async function markMessagesDone() {
  const today = $('emsg-start').value || ymd(new Date());
  showLoader();
  try {
    const res = await gasPost({ action: 'updateLastMessageSent', date: today });
    if (!res.ok) {
      showWriteFailure(res, 'Marking messages done');
      return;
    }
    const next = parseDate(today);
    if (next) { next.setDate(next.getDate() + 1); $('emsg-from').value = ymd(next); }
    $('emsg-from-label').textContent = '(last marked: ' + today + ', +1 day)';
    // Persist locally so re-opening the tab shows the new From date immediately
    // instead of the value baked into the last snapshot.
    S.snapConfig = today;
    cacheState();
    $('emsg-results').innerHTML = '<div class="card" style="text-align:center;color:#888;font-size:13px">Marked as done.</div>';
    $('emsg-mark-wrap').style.display = 'none';
    showAlert('Last message sent date updated to ' + today);
  } finally { hideLoader(); }
}
